# -*- coding: utf-8 -*-
"""Module 13: Mang du lieu may bay, AFDX va IMA. KHONG co slide cua giang vien: dung tu Tooley Ch.16 (tr.261-275) va Ch.18 (tr.294-306). (Module 05 chi nhac AFDX o muc 'chuan khac'.)
Cac phep tinh bang build/numlib/afdx.py (doi chieu o build/verify/verify_m13.py)."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'numlib'))
from mk import *
import afdx as F

def module(lang):
    bt = ''.join(f'<tr><td>{b}</td><td>{F.bag_hz(b):g}</td></tr>' for b in F.BAGS)
    bag_tab_vi = '<table class="t"><tr><th>BAG (ms)</th><th>Tần số tương đương (Hz)</th></tr>' + bt + '</table>'
    bag_tab_en = '<table class="t"><tr><th>BAG (ms)</th><th>Equivalent frequency (Hz)</th></tr>' + bt + '</table>'
    parts = [
     (('LAN dùng chung đường truyền hay chuyển mạch; Ethernet đa truy cập cần CSMA/CD còn chuyển mạch full-duplex thì không va chạm', 'A LAN shares or switches its medium; multiple-access ethernet needs CSMA/CD while switched full-duplex has no collisions'),
      [('Bốn cấu trúc LAN', 'Four LAN topologies'), ('Ethernet, CSMA/CD và lùi theo hàm mũ nhị phân', 'Ethernet, CSMA/CD and binary exponential back-off')], [
       ('LAN là mạng phạm vi hẹp tốc độ cao với bốn cấu trúc: sao, vòng, cây và bus', 'A LAN is a high-rate, short-range network with four topologies: star, ring, tree and bus',
        '<p>(Tooley 16.2, 16.3.) LAN nằm trong một địa điểm, ở avionics là một máy bay; nên theo chuẩn quốc tế, tốc độ cao (ví dụ 10 đến 100 Mbps), tầm vài trăm mét bằng cáp rẻ nhẹ, hỗ trợ nhiều nút độc lập, tin cậy, ít phụ thuộc thành phần tập trung và dễ mở rộng.</p>' + table(['Cấu trúc', 'Cách hoạt động'], [['Sao', 'phần tử chuyển mạch trung tâm cấp đường riêng giữa hai nút'], ['Vòng', 'vòng kín; nút phải chờ tới lượt rồi gửi gói có địa chỉ nguồn và đích'], ['Cây và bus', 'môi trường đa truy cập: tại một thời điểm chỉ một thiết bị phát; bus là cây một thân không nhánh']]),
        '<p>(Tooley 16.2, 16.3.) A LAN is confined to one site, in avionics one aircraft; it should follow an international standard, run at a high rate (e.g. 10 to 100 Mbps), reach several hundred metres on low-cost light cabling, support many independent nodes, be reliable, rely little on centralised parts and be easy to expand.</p>' + table(['Topology', 'How it works'], [['Star', 'a central switching element gives a dedicated path between two nodes'], ['Ring', 'a closed loop; a node waits its turn and sends a packet with source and destination addresses'], ['Tree and bus', 'multiple-access medium: only one device transmits at a time; a bus is a tree with one trunk and no branches']]),
        '<p>Cấu trúc đa truy cập (bus, cây) cần cơ chế tránh va chạm; cấu trúc sao chuyển mạch thì mỗi liên kết là điểm tới điểm. AFDX chọn sao nối tầng.</p>', '<p>Multiple-access topologies (bus, tree) need a collision-handling scheme; a switched star makes every link point to point. AFDX chose the cascaded star.</p>'),
       ('Ethernet đa truy cập dùng CSMA/CD và lùi ngẫu nhiên gấp đôi sau mỗi va chạm; chuyển mạch full-duplex loại bỏ va chạm', 'Multiple-access ethernet uses CSMA/CD and a random back-off that doubles after each collision; switched full-duplex removes collisions',
        '<p>Ethernet theo IEEE 802.3. <b>CSMA/CD</b>: <i>carrier sense</i> (biết bus rảnh hay bận), <i>multiple access</i> (nhiều host chung bus), <i>collision detection</i> (phát hiện va chạm). Quy tắc: nếu bus rảnh thì gửi, không thì chờ; nếu va chạm thì chờ rồi gửi lại. Khi cả hai host cần gửi lại, mỗi host chọn một thời điểm ngẫu nhiên trong một khoảng, và nếu lại va chạm thì khoảng gấp đôi: <b>lùi theo hàm mũ nhị phân</b>.</p>' + formula('Khoảng chọn sau lần va chạm thứ n', r'I_n=2^{\,n-1}\,T\qquad(n=3:\;4T,\;n=4:\;8T)') + '<p>Cấu hình bus là bán song công (half-duplex); cấu hình chuyển mạch cho phép song công toàn phần (full-duplex): gửi và nhận cùng lúc (Tooley 16.4).</p>',
        '<p>Ethernet follows IEEE 802.3. <b>CSMA/CD</b>: <i>carrier sense</i> (know whether the bus is idle or busy), <i>multiple access</i> (several hosts share the bus), <i>collision detection</i>. Rules: if the bus is idle send, otherwise wait; after a collision wait and resend. When both hosts must resend each picks a random instant within an interval, and if they collide again the interval doubles: <b>binary exponential back-off</b>.</p>' + formula('Interval after collision n', r'I_n=2^{\,n-1}\,T\qquad(n=3:\;4T,\;n=4:\;8T)') + '<p>The bus arrangement is half-duplex; a switched arrangement allows full-duplex: sending and receiving at the same time (Tooley 16.4).</p>',
        '<p>Điều Ethernet thương mại không bảo đảm là thời gian truyền tối đa: sau nhiều va chạm dữ liệu quan trọng có thể đến quá muộn. Đó là lý do hàng không cần mạng tất định.</p>', '<p>What commercial ethernet does not guarantee is the maximum transfer time: after many collisions critical data can arrive too late. That is why aviation needs a deterministic network.</p>'),
     ]),
     (('AFDX bổ sung tính tất định và băng thông bảo đảm cho Ethernet chuyển mạch bằng liên kết ảo, BAG và khung có số thứ tự', 'AFDX adds determinism and guaranteed bandwidth to switched ethernet with virtual links, the BAG and sequenced frames'),
      [('Switch, end system và tính tất định', 'Switch, end system and determinism'), ('Liên kết ảo và BAG', 'Virtual links and the BAG'), ('Khung AFDX và độ tin cậy', 'The AFDX frame and reliability')], [
       ('AFDX (ARINC 664) dùng switch lưu và chuyển tiếp nên loại bỏ va chạm, và thêm QoS tất định', 'AFDX (ARINC 664) uses store-and-forward switches so collisions disappear, and adds deterministic QoS',
        '<p>(Tooley 16.5, 16.6.) AFDX triển khai chuẩn <b>ARINC 664</b>, dựa trên Ethernet IEEE 802.3 và linh kiện thương mại (COTS); phát triển cho Airbus A380, nay có trên Boeing 787. Cấu trúc <b>sao nối tầng</b>: hệ avionics nối bằng liên kết full-duplex (hai cặp xoắn) tới switch; CPU của switch xem địa chỉ đích rồi đặt gói vào bảng chuyển tiếp và chép tới bộ đệm TX. Mỗi gói được đệm nên không va chạm. <b>Tính tất định</b> nghĩa là có thời gian trễ tối đa bảo đảm từ nút này tới nút kia; <b>QoS</b> là khả năng bảo đảm mức hiệu năng của luồng dữ liệu. <b>End system</b> là giao diện giữa phần cứng avionics và mạng.</p>',
        '<p>(Tooley 16.5, 16.6.) AFDX implements <b>ARINC 664</b>, based on IEEE 802.3 ethernet and commercial off-the-shelf (COTS) parts; developed for the Airbus A380, now on the Boeing 787. A <b>cascaded star</b>: avionic systems connect by full-duplex links (two twisted pairs) to a switch; the switch CPU reads the destination address, puts the packet in the forwarding table and copies it to the TX buffer. Every packet is buffered so there are no collisions. <b>Determinism</b> means a guaranteed maximum delay from node to node; <b>QoS</b> is the ability to guarantee a level of performance of the data flow. The <b>end system</b> is the interface between the avionics hardware and the network.</p>',
        '<p>Bộ đệm đủ lớn thì gói có thể chậm vì tắc nghẽn nhưng không bị mất vì tràn. Nếu ARINC 429 tốc độ cao là 100 kbit/s thì mạng 100 Mbit/s nhanh gấp 1 000 lần: khớp với "một nghìn lần băng thông" của Tooley 18.5.</p>', '<p>With large enough buffers a packet may be delayed by congestion but not lost by overflow. If high-speed ARINC 429 is 100 kbit/s then a 100 Mbit/s network is 1,000 times faster: matching Tooley 18.5\'s "one thousand times the bandwidth".</p>'),
       ('Liên kết ảo (VL) chia băng thông vật lý và BAG giới hạn tốc độ gửi: tốc độ bit lớn nhất = $L_{max}\\times8\\times1000/\\text{BAG}$', 'Virtual links (VL) share the physical bandwidth and the BAG limits the send rate: maximum bit rate = $L_{max}\\times8\\times1000/\\text{BAG}$',
        '<p>(Tooley 16.7, 16.8.) <b>VL</b> là kênh logic một chiều từ đúng một end system tới một hoặc nhiều end system khác; gói được định tuyến theo VL ID 16 bit (trong hai byte cuối của địa chỉ MAC đích, sau trường hằng số 32 bit). Tổng băng thông các VL không vượt băng thông liên kết; liên lạc hai chiều cần một VL bổ sung. <b>BAG</b> là khoảng cách tối thiểu giữa hai khung trên một VL, từ 1 đến 128 ms:</p>' + bag_tab_vi + formula('Tốc độ bit lớn nhất của VL', r'R_{max}=\frac{L_{max}\times8\times1000}{\text{BAG(ms)}}\;\;\Rightarrow\;\;\frac{1518\times8\times1000}{4}=3{,}036\times10^{6}\text{ bit/s}') + '<p>Chọn BAG: dữ liệu 100 lần mỗi giây cần BAG không quá 8 ms vì 125 Hz lớn hơn 100 Hz.</p>',
        '<p>(Tooley 16.7, 16.8.) A <b>VL</b> is a one-way logical channel from exactly one end system to one or more others; packets are routed by a 16-bit VL ID (in the last two bytes of the destination MAC address, after a 32-bit constant field). The VLs\' total bandwidth cannot exceed the link bandwidth; two-way communication needs a complementary VL. The <b>BAG</b> is the minimum interval between two frames on a VL, from 1 to 128 ms:</p>' + bag_tab_en + formula('Maximum bit rate of a VL', r'R_{max}=\frac{L_{max}\times8\times1000}{\text{BAG(ms)}}\;\;\Rightarrow\;\;\frac{1518\times8\times1000}{4}=3.036\times10^{6}\text{ bit/s}') + '<p>Choosing a BAG: data recurring 100 times a second needs a BAG of at most 8 ms because 125 Hz exceeds 100 Hz.</p>',
        '<p>Tooley Chương 16 câu 5 hỏi BAG lớn nhất cho 400 thông điệp mỗi giây; theo bảng 16.1 và quy tắc trên đáp án là 2 ms (500 Hz), không phải 4 ms (250 Hz) như khoá in.</p>', '<p>Tooley Chapter 16 Q5 asks for the largest BAG for 400 messages a second; by Table 16.1 and the rule above the answer is 2 ms (500 Hz), not 4 ms (250 Hz) as the printed key says.</p>'),
       ('Khung AFDX dài 64 đến 1 518 byte, có số thứ tự 0 đến 255 và CRC 4 byte; mạng A và B dự phòng cho nhau', 'An AFDX frame is 64 to 1,518 bytes with a sequence number 0 to 255 and a 4-byte CRC; networks A and B back each other up',
        '<p>(Tooley 16.9.) Khung dựa trên khung IEEE 802.3. Phần tử (byte): tiền tố 7 và SFD 1 (không tính vào độ dài khung), MAC đích 6, MAC nguồn 6, Type 2 (luôn 0x0800 = IPv4), tiêu đề IP 20, UDP 8, payload AFDX, đệm (0 đến 16), số thứ tự SN 1, FCS 4 (CRC); sau đó khoảng cách giữa khung 12 byte.</p>' + formula('Độ dài khung', r'L=6+6+2+20+8+\max(P,17)+1+4\quad\Rightarrow\quad P=1\text{ đến }1471:\;L=64\text{ đến }1518\text{ byte}') + '<p>SN bắt đầu từ 0 khi khởi động, tăng tới 255 rồi quay về 1. <b>Kiểm tra toàn vẹn</b> kiểm SN theo đúng thứ tự; <b>quản lý dự phòng</b> loại bỏ khung trùng. Mạng B (xanh lam) truyền bản sao của mạng A (đỏ): bảo vệ khỏi lỗi cáp, đầu nối, switch, nhiễu và RFI.</p>',
        '<p>(Tooley 16.9.) The frame follows the IEEE 802.3 frame. Fields (bytes): preamble 7 and SFD 1 (not counted in the frame length), MAC destination 6, MAC source 6, Type 2 (always 0x0800 = IPv4), IP header 20, UDP 8, AFDX payload, padding (0 to 16), sequence number SN 1, FCS 4 (a CRC); then a 12-byte inter-frame gap.</p>' + formula('Frame length', r'L=6+6+2+20+8+\max(P,17)+1+4\quad\Rightarrow\quad P=1\text{ to }1471:\;L=64\text{ to }1518\text{ bytes}') + '<p>The SN starts at 0 at start-up, increments to 255 and wraps to 1. <b>Integrity checking</b> checks the SNs are in strict order; <b>redundancy management</b> drops replicas. Network B (blue) carries a copy of network A (red): protection against cable faults, connectors, switches, noise and RFI.</p>',
        f'<p>Site đã kiểm số học khung bằng hai cách: payload 1 cần đệm 16 byte (tổng {F.frame_len(1)} byte), payload 1 471 không đệm (tổng {F.frame_len(1471)} byte). Truyền khung dài nhất mất {F.tx_time(1518, 10e6) * 1e3:.4f} ms ở 10 Mbit/s và {F.tx_time(1518, 100e6) * 1e6:.2f} μs ở 100 Mbit/s (chỉ tính khung); khoảng cách 12 byte kéo dài {F.ifg(100e6) * 1e6:.2f} μs ở 100 Mbit/s.</p>'.replace('.', ',') if False else f'<p>Site đã kiểm số học khung bằng hai cách: payload 1 cần đệm 16 byte (tổng {F.frame_len(1)} byte), payload 1471 không đệm (tổng {F.frame_len(1471)} byte). Truyền khung dài nhất mất {str(round(F.tx_time(1518, 10e6) * 1e3, 4)).replace(".", ",")} ms ở 10 Mbit/s và {str(round(F.tx_time(1518, 100e6) * 1e6, 2)).replace(".", ",")} μs ở 100 Mbit/s (chỉ tính khung); khoảng cách 12 byte kéo dài {str(round(F.ifg(100e6) * 1e6, 2)).replace(".", ",")} μs ở 100 Mbit/s.</p>',
        f'<p>The site checked the frame arithmetic two ways: a 1-byte payload needs 16 bytes of padding ({F.frame_len(1)} bytes in all), a 1,471-byte payload none ({F.frame_len(1471)} bytes). The longest frame takes {F.tx_time(1518, 10e6) * 1e3:.4f} ms at 10 Mbit/s and {F.tx_time(1518, 100e6) * 1e6:.2f} μs at 100 Mbit/s (frame only); the 12-byte gap lasts {F.ifg(100e6) * 1e6:.2f} μs at 100 Mbit/s.</p>'),
     ]),
     (('IMA gom nhiều ứng dụng avionics vào một nền tính toán dùng chung nối bằng mạng AFDX, mỗi ứng dụng trong một phân vùng riêng', 'IMA gathers many avionic applications onto one shared computing platform joined by an AFDX network, each in its own partition'),
      [('Vì sao IMA và IMA là gì', 'Why IMA, and what it is'), ('Kiến trúc IMA so với liên hợp', 'IMA architecture versus federated'), ('Nền IMA: RTOS, phân vùng, ARINC 653', 'The IMA platform: RTOS, partitions, ARINC 653')], [
       ('IMA thay mỗi hệ một máy tính bằng một nền tính toán dùng chung để giảm cáp, khối lượng và chi phí', 'IMA replaces one computer per system with one shared computing platform to cut cabling, weight and cost',
        '<p>(Tooley 16.1, 18.1, 18.2.) Trước đây mỗi hệ avionics có máy tính riêng, thường trong một LRU: nhiều máy tính, nhiều cáp, nặng và tốn điện. <b>IMA</b> là khái niệm (không phải một công nghệ cụ thể): nhiều ứng dụng chạy trên nền tính toán dùng chung, nối bằng mạng đa kênh tốc độ cao, độ toàn vẹn cao. Ba yếu tố: nền tính toán tích hợp cao; mạng dùng chung dự phòng kép (ARINC 664/AFDX, truyền đa hướng, switch thông minh); kiến trúc phân tán gồm ứng dụng phần mềm tập trung và các end system đặt từ xa. Ví dụ ứng dụng: điều hoà không khí và tăng áp cabin, năng lượng, nhiên liệu, khí nén và thuỷ lực, phanh và càng đáp, bảo vệ băng và mưa, cảm biến tiệm cận, phát hiện cháy.</p>',
        '<p>(Tooley 16.1, 18.1, 18.2.) Each avionic system used to have its own computer, often in an LRU: many computers, much cabling, heavy and power-hungry. <b>IMA</b> is a concept (not one specific technology): many applications run on a shared computing platform joined by a high-speed, high-integrity multiplexed network. Three elements: a high-integrity common computing resource; a shared dual-redundant network (ARINC 664/AFDX, multicast, intelligent switches); a distributed architecture of centrally computed software applications and remotely located end systems. Example applications: air conditioning and cabin pressurisation, energy, fuel, pneumatics and hydraulics, brakes and landing gear, ice and rain protection, proximity sensing, fire detection.</p>',
        '<p>Lợi ích (Tooley 18.1): quản lý nhiều chức năng hơn, giảm khối lượng cáp (tiết kiệm nhiên liệu và chi phí), hỗ trợ chức năng mới như giám sát tình trạng máy bay, hỗ trợ đa nguồn, giảm phụ tùng.</p>', '<p>Benefits (Tooley 18.1): manage more functions, lighter cabling (saving fuel and cost), support for new functions such as aircraft condition monitoring, multi-source support, fewer spares.</p>'),
       ('So với avionics liên hợp, IMA tập trung xử lý, dùng một mạng xương sống chung và cách ly phần mềm bằng phân vùng logic', 'Compared with federated avionics, IMA centralises processing, uses one common backbone and isolates software by logical partitions',
        table(['Tiêu chí', 'Liên hợp (federated)', 'IMA'], [['Xử lý', 'nhiều máy tính nhúng riêng cho từng chức năng', 'tập trung trên nền IMA dùng chung, ứng dụng được phân vùng'], ['Liên kết dữ liệu và cáp', 'nhiều bus tốc độ thấp và trung bình (ARINC 429, 629)', 'một mạng xương sống chuyển mạch tốc độ cao (ARINC 664, AFDX)'], ['Phần mềm ứng dụng', 'cách ly vật lý, nằm trên từng LRU', 'cách ly logic, nhiều ứng dụng trên một nền'], ['Nhà cung cấp', 'hạn chế vài nguồn', 'lý tưởng là mở (đa nguồn)']]) + '<p>Airbus A380: nửa mở (một nhà cung cấp tủ phần cứng, hệ điều hành chung); Boeing 777 dùng AIMS của Honeywell nên là hệ <b>đóng</b>; máy bay nhỏ của Bombardier, Embraer thường đóng (Tooley 18.2.1, 18.3).</p>',
        table(['Feature', 'Federated', 'IMA'], [['Processing', 'many embedded computers dedicated to separate functions', 'centralised on a shared IMA platform with partitioned applications'], ['Data interconnection and cabling', 'many low and medium speed buses (ARINC 429, 629)', 'one common high-speed switched backbone (ARINC 664, AFDX)'], ['Application software', 'physically firewalled, on individual LRUs', 'logically firewalled, several applications on one platform'], ['Suppliers', 'restricted to a few sources', 'ideally open (multiple sources)']]) + '<p>Airbus A380: semi-open (one hardware-cabinet supplier, a shared operating system); the Boeing 777 uses Honeywell\'s AIMS so it is <b>closed</b>; smaller Bombardier and Embraer aircraft are typically closed (Tooley 18.2.1, 18.3).</p>',
        '<p>Mỗi LRU dùng một end system thông minh nối với switch gần nhất nên không cần cáp riêng về nền IMA. Trên A380, mô-đun CPIOM (tính toán và vào/ra) chứa ứng dụng; mô-đun IOM chỉ đổi dữ liệu không-AFDX sang AFDX.</p>', '<p>Each LRU uses an intelligent end system to connect to the nearest switch so it needs no individual cable back to the IMA platform. On the A380 the CPIOM modules (computing and I/O) host applications; the IOM modules only convert non-AFDX data to AFDX.</p>'),
       ('Nền IMA chạy một RTOS cấp cho mỗi ứng dụng một phân vùng bộ nhớ và một lát thời gian theo ARINC 653', 'The IMA platform runs an RTOS that gives each application a memory partition and a time slice, following ARINC 653',
        '<p>(Tooley 18.4, 18.5.) RTOS quản lý phân vùng và lập lịch. Một <b>bộ điều hành ứng dụng (APEX)</b> cấp phát bộ nhớ và thời gian, quản lý tiến trình, truyền thông giữa phân vùng và xử lý lỗi. Phần mềm ứng dụng không thuộc lõi hệ điều hành nên có thể kiểm chứng và chứng nhận độc lập. Chuẩn hàng đầu là <b>ARINC 653</b>, phải tương thích ngược với LRU nối ARINC 629 và hệ ARINC 429. Ví dụ điều khiển càng đáp: phần mềm ở nền IMA, cảm biến tiệm cận qua bộ tập trung dữ liệu (PSDC, RDC) và các switch AFDX; mạng ARINC 664 có băng thông gấp khoảng một nghìn lần ARINC 429 mà nó thay thế.</p>',
        '<p>(Tooley 18.4, 18.5.) The RTOS manages partitioning and scheduling. An <b>application executive (APEX)</b> allocates memory and time, manages processes, partition communication and error handling. Application software is not part of the core operating system so it can be validated and certified independently. The leading standard is <b>ARINC 653</b>, which must stay compatible with LRUs on ARINC 629 and ARINC 429 systems. Landing-gear example: the software sits on the IMA platform, proximity sensors reach it through data concentrators (PSDC, RDC) and AFDX switches; the ARINC 664 network has about a thousand times the bandwidth of the ARINC 429 bus it replaces.</p>',
        '<p>Các ứng dụng tới hạn như điều khiển bay và động cơ vẫn có thể nằm trên máy tính chuyên dụng theo kiến trúc liên hợp: không bắt buộc chuyển mọi thứ lên nền IMA.</p>', '<p>Critical applications such as flight and engine control may stay on dedicated computers in a federated architecture: not everything has to move to the IMA platform.</p>'),
     ]),
    ]
    exs = [
      (('Ví dụ 1: tốc độ bit lớn nhất của VL (Tooley)', 'Example 1: maximum bit rate of a VL (Tooley)'), ('Khung 1 518 byte, BAG 4 ms: $1518\\times8\\times1000/4=3\\,036\\,000$ bit/s ≈ 3 Mbit/s.', 'Frame 1,518 bytes, BAG 4 ms: $1518\\times8\\times1000/4=3{,}036{,}000$ bit/s ≈ 3 Mbit/s.'), f'{F.bitrate(1518, 4):,.0f} bit/s'),
      (('Ví dụ 2: chọn BAG cho 400 thông điệp mỗi giây', 'Example 2: choosing a BAG for 400 messages a second'), ('Cần tần số BAG ≥ 400 Hz: 500 Hz ứng với 2 ms; 250 Hz (4 ms) không đủ.', 'The BAG frequency must be ≥ 400 Hz: 500 Hz is 2 ms; 250 Hz (4 ms) is not enough.'), f'{F.max_bag(400)} ms'),
      (('Ví dụ 3: tốc độ bit cho khung 256 byte, BAG 128 ms (Tooley Chương 16 câu 6)', 'Example 3: bit rate for 256-byte frames and a 128 ms BAG (Tooley Chapter 16 Q6)'), ('$256\\times8\\times1000/128=16\\,000$ bit/s.', '$256\\times8\\times1000/128=16{,}000$ bit/s.'), f'{F.bitrate(256, 128):,.0f} bit/s'),
      (('Ví dụ 4: độ dài khung nhỏ nhất và lớn nhất', 'Example 4: the minimum and maximum frame length'), ('Nhỏ nhất: $6+6+2+20+8+17+1+4=64$ byte; lớn nhất với payload 1 471: 1 518 byte.', 'Minimum: $6+6+2+20+8+17+1+4=64$ bytes; maximum with a 1,471-byte payload: 1,518 bytes.'), f'{F.frame_len(1)} byte; {F.frame_len(1471)} byte'),
      (('Ví dụ 5: số thứ tự quay vòng', 'Example 5: sequence-number wrap'), ('SN: 253, 254, 255, rồi 1, 2 (quay về 1 chứ không phải 0).', 'SN: 253, 254, 255, then 1, 2 (it wraps to 1, not 0).'), ', '.join(str(x) for x in (253, 254, 255, F.sn_next(255), F.sn_next(F.sn_next(255))))),
    ]
    return build(parts, exs,
        ('Mạng dữ liệu của máy bay hiện đại: LAN và Ethernet, AFDX (ARINC 664) với liên kết ảo, BAG, khung và dự phòng, rồi IMA đặt nhiều ứng dụng avionics lên một nền tính toán dùng chung. Dựng từ Tooley Chương 16 và 18 (không có slide của giảng viên; Module 05 chỉ nhắc AFDX).',
         'The data networks of a modern aircraft: LANs and ethernet, AFDX (ARINC 664) with virtual links, the BAG, frames and redundancy, then IMA putting many avionic applications on one shared computing platform. Built from Tooley Chapters 16 and 18 (no lecturer slides; Module 05 only mentions AFDX).'),
        [('mô tả bốn cấu trúc LAN, CSMA/CD và lùi theo hàm mũ nhị phân', 'describe the four LAN topologies, CSMA/CD and binary exponential back-off'), ('giải thích vì sao AFDX là tất định và vai trò của switch, end system, liên kết ảo', 'explain why AFDX is deterministic and the roles of the switch, end system and virtual links'),
         ('chọn BAG và tính tốc độ bit lớn nhất của một VL', 'choose a BAG and compute the maximum bit rate of a VL'), ('tính độ dài khung AFDX, thời gian truyền và số thứ tự quay vòng', 'compute the AFDX frame length, transmit time and the wrapping sequence number'),
         ('phân biệt avionics liên hợp với IMA, IMA mở với đóng, và nêu vai trò của RTOS, APEX, ARINC 653', 'tell federated avionics from IMA, open IMA from closed, and state the roles of the RTOS, APEX and ARINC 653')],
        ('Module không có slide của giảng viên. Tooley Chương 16 (tr.261 đến 275, PDF tr.275 đến 289) và Chương 18 (tr.294 đến 306, PDF tr.308 đến 320). Câu hỏi gốc: 16 câu Chương 16 (khoá A.16, tr.381) và 10 câu Chương 18 (khoá A.18, tr.382), đọc từ ảnh quét. Chương 17 (VHDL) ở Module 14. Floyd Chương 13 (§13-6 đến 13-10: bus chung như USB, SPI, I²C) là nền tảng bổ sung nhưng không có câu hỏi trong module này.',
         'The module has no lecturer slides. Tooley Chapter 16 (pp.261 to 275, PDF pp.275 to 289) and Chapter 18 (pp.294 to 306, PDF pp.308 to 320). Original questions: 16 questions of Chapter 16 (key A.16, p.381) and 10 of Chapter 18 (key A.18, p.382), read from the scanned pages. Chapter 17 (VHDL) is in Module 14. Floyd Chapter 13 (§13-6 to 13-10: general buses such as USB, SPI, I²C) is extra background but has no questions in this module.'),
        [('Tooley Chương 16 câu 5: khoá in (b) 4 ms; theo bảng 16.1 và quy tắc của chính cuốn sách (dữ liệu 100 lần mỗi giây cần BAG không quá 8 ms vì 125 Hz lớn hơn 100 Hz) thì 400 lần mỗi giây cần tần số BAG ít nhất 400 Hz: 2 ms (500 Hz). Site dùng (a).', 'Tooley Chapter 16 Q5: printed key (b) 4 ms; by Table 16.1 and the book\'s own rule (data 100 times a second needs a BAG of at most 8 ms because 125 Hz exceeds 100 Hz) 400 times a second needs a BAG frequency of at least 400 Hz: 2 ms (500 Hz). The site uses (a).'),
         ('Tooley Chương 16 câu 9: khoá in (b) lớp IP; nhưng câu 11 (khoá a) cho thứ tự phát UDP, IP, lớp liên kết nên tiêu đề Ethernet do lớp liên kết thêm vào. Site dùng (c).', 'Tooley Chapter 16 Q9: printed key (b) IP layer; but Q11 (key a) gives the transmit order UDP, IP, link layer so the ethernet header is added by the link layer. The site uses (c).'),
         ('Khoá A.16 có 20 mục nhưng sách chỉ in 16 câu trắc nghiệm ở mục 16.11; bốn mục cuối (17 c, 18 a, 19 b, 20 b) không có câu tương ứng.', 'Key A.16 has 20 entries but the book prints only 16 multiple-choice questions in 16.11; the last four entries (17 c, 18 a, 19 b, 20 b) have no matching question.'),
         ('Tooley 16.9 nói payload AFDX 1 đến 1 471 byte, còn khung ghi chú "payload từ 17 đến 1 471, nhỏ hơn 17 thì thêm đệm": hai cách nói nhất quán khi gộp payload và đệm (tối thiểu 17 byte).', 'Tooley 16.9 says the AFDX payload is 1 to 1,471 bytes while a key-point box says "17 to 1,471, below 17 padding is added": the two statements agree once payload and padding are combined (at least 17 bytes).'),
         ('Tooley Test Your Understanding 16.8 hỏi khoảng cách giữa khung ở 100 Mbit/s và thời gian truyền khung dài nhất ở 10 Mbit/s: site tính 0,96 μs (12 byte) và 1,2144 ms (chỉ khung; 1,2304 ms nếu cộng tiền tố và khoảng cách).', 'Tooley Test Your Understanding 16.8 asks for the inter-frame gap at 100 Mbit/s and the transmit time of the longest frame at 10 Mbit/s: the site computes 0.96 μs (12 bytes) and 1.2144 ms (frame only; 1.2304 ms with the preamble and gap).')])
